#!/usr/bin/env bun
/**
 * manage_dispatch_loop.ts — Track the auto-dispatch loop counter in
 * session.json to prevent infinite agent handoff loops.
 *
 * Usage:
 *   manage_dispatch_loop.ts --session session.json
 *     [--new-event-count N] [--directive NAME]
